import { getAllProducts } from '@/lib/db';
import { cacheTag } from 'next/cache';
import { revalidateTag } from 'next/cache';
import { Suspense } from 'react';

// Define the shape of a product
interface Product {
  id: number;
  name: string;
  price: number;
}

// Cached data fetching function
async function getCachedProducts() {
  'use cache';
  cacheTag('products');
  return getAllProducts();
}

// Child component that fetches product data
async function ProductList() {
  const products = await getCachedProducts();

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-8">
      {products.map((product: Product) => (
        <div key={product.id} className="p-4 border rounded shadow-sm bg-white">
          <h3 className="font-semibold text-lg">{product.name}</h3>
          <p className="text-green-600 font-medium">${product.price}</p>
        </div>
      ))}
    </div>
  );
}

export default function Page() {
  // Inline server action to invalidate cache
  async function invalidateProducts() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div className="container mx-auto p-8 max-w-4xl">
      <h1 className="text-3xl font-bold mb-6">Product Catalog</h1>

      <Suspense fallback={<div className="p-4 text-gray-500">Loading products...</div>}>
        <ProductList />
      </Suspense>

      <div className="p-6 bg-gray-50 rounded-lg border border-gray-200">
        <h2 className="text-xl font-semibold mb-2">Cache Management</h2>
        <p className="mb-4 text-gray-600">
          The product list above is cached with the tag <code>"products"</code>. 
          Submitting the form below will invalidate this cache, forcing a fresh data fetch on the next render.
        </p>

        <form action={invalidateProducts}>
          <button 
            type="submit"
            className="px-4 py-2 bg-blue-600 text-white font-medium rounded hover:bg-blue-700 transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
          >
            Invalidate "products" Cache
          </button>
        </form>
      </div>
    </div>
  );
}

